G=load(); print(sorted(G))

def solve(inp):
    H,W=len(inp),len(inp[0]); bg=inp[0][0]
    pts=[]
    for i in range(H):
        for j in range(W):
            if inp[i][j]!=bg: pts.append((i,j,inp[i][j]))
    out=[r[:] for r in inp]
    # pair groups sharing a diagonal within their own color; extend to grid edges
    for c in {p[2] for p in pts}:
        cs=[(i,j) for i,j,v in pts if v==c]
        used=set()
        for a,b in itertools.combinations(cs,2):
            di,dj=b[0]-a[0],b[1]-a[1]
            if di and dj: continue
            g=math.gcd(abs(di),abs(dj))
            if g==0: continue
            step=(di//g, dj//g)
            ok=True
            k=1
            while k<g:
                ni,nj=a[0]+step[0]*k,a[1]+step[1]*k
                if (ni,nj)!=b and out[ni][nj]!=bg: ok=False;break
                k+=1
            if not ok: continue
            key=frozenset([(a,b)] if False else tuple(sorted([a,b])))
            if key in used: continue
            used.add(key)
            # extend BOTH directions along this line across whole grid
            for sgn in (1,-1):
                ii,jj=a
                while True:
                    ii+=sgn*step[0]; jj+=sgn*step[1]
                    if not(0<=ii<H and 0<=jj<W): break
                    if out[ii][jj]==bg: out[ii][jj]=c
                    else: break   # blocked by non-bg
    return out

