            elif a[0]-a[1]==b[0]-b[1]: si,sj=1,1
            else: continue
            i,j=a
            while (i,j)!=b:
                i+=si; j+=sj
                if not(0<=i<H and 0<=j<W): break
                marked[i][j]=True
    for c in cols:
